// Generated by scripts/split.py from cockpit/: edit there and run it again
import { expect, test } from 'claude-code/testing'
import type { Register } from 'claude-code'

// cockpit-core as the chat meets it: it provides $.cockpit, whose calls reach the test's hooks beneath
const core: Register = on => {
  on('engine.create', async (_$, e, next) => ({ ...(await next(e)), cockpit: { set: async () => true, act: async () => null, tab: async () => true } }))
}

const BAND = { plugin: 'cockpit-chat', component: 'AbovePrompt', requestId: 'band', props: { hasSurvey: false, isWorking: false, maxRows: 12, bodyColumns: 90, scroll: { offset: 0, bodyRows: 30 }, view: {} } }

for (const surface of ['terminal', 'desktop'] as const) {
  test(`the band draws core's figures on ${surface}, and Focus changes core's state`, { plugins: [{ name: 'cockpit-core', register: core }] }, async ($, on) => {
    const asked: unknown[] = []
    on('cockpit.set' as never, (async (_: unknown, e: { patch: unknown }) => (asked.push(e.patch), { value: true })) as never)
    on('clock.now', async () => ({ value: 1_000_000 }))
    const ui = await $.ui.mount({ ...BAND, surface } as never)
    expect(JSON.stringify(await ui.drawn())).toContain('Focus')
    await ui.press({ key: 'ph-focus' })
    expect(JSON.stringify(asked)).toContain('"focus":false')
    await ui.unmount()
  })
}
